/// <summary>
///     <para xml:lang="en">
///         Adds <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.CombatOnly" /> mod piles to
///         <see cref="P:MegaCrit.Sts2.Core.Entities.Players.PlayerCombatState.AllPiles" />.
///     </para>
///     <para xml:lang="zh-CN">
///         将 <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.CombatOnly" /> 模组牌堆加入
///         <see cref="P:MegaCrit.Sts2.Core.Entities.Players.PlayerCombatState.AllPiles" />。
///     </para>
/// </summary>
/// <remarks>
///     <para xml:lang="en">
///         The postfix preserves the existing result and appends missing RitsuLib piles.
///     </para>
///     <para xml:lang="en">
///         The combined array is also stored in <c>_piles</c> so later getter calls reuse it.
///     </para>
///     <para xml:lang="zh-CN">
///         后置补丁会保留现有结果，并在其后追加缺失的 RitsuLib 牌堆。
///     </para>
///     <para xml:lang="zh-CN">
///         合并后的数组也会写入 <c>_piles</c>，供后续属性访问复用。
///     </para>
/// </remarks>
internal sealed class ModCardPileAllPilesPatch : IPatchMethod
{
	public static string PatchId => "ritsulib_player_combat_state_all_piles_append";

	public static string Description => "Append ritsulib CombatOnly mod piles to PlayerCombatState.AllPiles without transpiling";

	public static bool IsCritical => false;

	public static ModPatchTarget[] GetTargets()
	{
		return new ModPatchTarget[1]
		{
			new ModPatchTarget(typeof(PlayerCombatState), "AllPiles", (MethodType)1)
		};
	}

	public static void Postfix(PlayerCombatState __instance, ref IReadOnlyList<CardPile> __result)
	{
		ModCardPileDefinition[] combatDefinitionsSnapshot = ModCardPileRegistry.GetCombatDefinitionsSnapshot();
		if (combatDefinitionsSnapshot.Length == 0 || ContainsAllDefinitions(__result, combatDefinitionsSnapshot))
		{
			return;
		}
		IReadOnlyCollection<ModCardPile> orCreateCombatPiles = ModCardPileStorage.GetOrCreateCombatPiles(__instance);
		if (orCreateCombatPiles.Count == 0 || ContainsAll(__result, orCreateCombatPiles))
		{
			return;
		}
		CardPile[] array = (CardPile[])(object)new CardPile[__result.Count + orCreateCombatPiles.Count];
		for (int i = 0; i < __result.Count; i++)
		{
			array[i] = __result[i];
		}
		int count = __result.Count;
		foreach (ModCardPile item in orCreateCombatPiles)
		{
			array[count++] = (CardPile)(object)item;
		}
		__instance._piles = array;
		__result = array;
	}

	private static bool ContainsAll(IReadOnlyList<CardPile> haystack, IReadOnlyCollection<ModCardPile> needles)
	{
		return needles.Select((ModCardPile needle) => haystack.Any((CardPile cardPile) => (object)cardPile == needle)).All((bool found) => found);
	}

	private static bool ContainsAllDefinitions(IReadOnlyList<CardPile> haystack, IReadOnlyList<ModCardPileDefinition> definitions)
	{
		foreach (ModCardPileDefinition definition in definitions)
		{
			bool flag = false;
			foreach (CardPile item in haystack)
			{
				if (item is ModCardPile modCardPile && (object)modCardPile.Definition == definition)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				return false;
			}
		}
		return true;
	}
}
