using System;
using System.Threading;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Models;

namespace STS2RitsuLib.CardPiles;

internal static class ModExtraHandSemanticContext
{
	private sealed class State(CardModel card, State? previous)
	{
		public CardModel Card { get; } = card;

		public State? Previous { get; } = previous;
	}

	private sealed class Scope(State? previous) : IDisposable
	{
		private bool _disposed;

		private State? _previous = previous;

		public void Dispose()
		{
			if (!_disposed)
			{
				_disposed = true;
				Current.Value = previous;
				previous = null;
			}
		}
	}

	private static readonly AsyncLocal<State?> Current = new AsyncLocal<State>();

	internal static IDisposable? EnterPlayEvaluation(CardModel card)
	{
		//IL_0015: Unknown result type (might be due to invalid IL or missing references)
		if (IsActive(card))
		{
			return null;
		}
		CardPile pile = card.Pile;
		if (pile == null || !ModCardPileRegistry.TryGetByPileType(pile.Type, out ModCardPileDefinition definition) || definition.Style != ModCardPileUiStyle.ExtraHand || !definition.ExtraHand.AllowCardPlay)
		{
			return null;
		}
		State value = Current.Value;
		Current.Value = new State(card, value);
		return new Scope(value);
	}

	internal static bool IsActive(CardModel card)
	{
		for (State state = Current.Value; state != null; state = state.Previous)
		{
			if (state.Card == card)
			{
				return true;
			}
		}
		return false;
	}
}
