using STS2RitsuLib.Content;
using STS2RitsuLib.Utils;

namespace STS2RitsuLib.CardPiles;

/// <summary>
///     <para xml:lang="en">
///         Registers custom card piles for one mod and resolves their definitions and dynamic
///         <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.PileType" /> values.
///     </para>
///     <para xml:lang="zh-CN">
///         为单个模组注册自定义卡牌牌堆，并解析其定义与动态 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.PileType" /> 值。
///     </para>
/// </summary>
/// <remarks>
///     <para xml:lang="en">
///         A single global <see cref="T:STS2RitsuLib.Utils.DynamicEnumValueMinter`1" /> reserves the high value band
///         (<c>[0x4000_0000, 0x7FFF_FFFF]</c>). Registrations are shared process-wide and freeze before
///         model initialization.
///     </para>
///     <para xml:lang="en">
///         Use <see cref="M:STS2RitsuLib.CardPiles.ModCardPileRegistry.For(System.String)" /> with the owning mod ID. Definitions remain available to global lookup by
///         pile ID or dynamic value.
///     </para>
///     <para xml:lang="zh-CN">
///         单个全局 <see cref="T:STS2RitsuLib.Utils.DynamicEnumValueMinter`1" /> 会保留高值区间
///         （<c>[0x4000_0000, 0x7FFF_FFFF]</c>）。注册信息在进程内共享，并会在模型初始化前冻结。
///     </para>
///     <para xml:lang="zh-CN">
///         使用 <see cref="M:STS2RitsuLib.CardPiles.ModCardPileRegistry.For(System.String)" /> 和所属模组 ID 获取注册表。定义仍可通过牌堆 ID 或动态值进行全局查找。
///     </para>
/// </remarks>
public sealed class ModCardPileRegistry
{
	private static readonly Lock SyncRoot = new Lock();

	private static readonly Dictionary<string, ModCardPileRegistry> Registries = new Dictionary<string, ModCardPileRegistry>(StringComparer.OrdinalIgnoreCase);

	private static readonly Dictionary<string, ModCardPileDefinition> Definitions = new Dictionary<string, ModCardPileDefinition>(StringComparer.OrdinalIgnoreCase);

	private static readonly Dictionary<PileType, ModCardPileDefinition> DefinitionsByPileType = new Dictionary<PileType, ModCardPileDefinition>();

	private static ModCardPileDefinition[] _combatDefinitionsSnapshot = Array.Empty<ModCardPileDefinition>();

	private static ModCardPileDefinition[] _definitionsSnapshot = Array.Empty<ModCardPileDefinition>();

	private readonly Logger _logger;

	private readonly string _modId;

	private string? _freezeReason;

	/// <summary>
	///     <para xml:lang="en">Gets whether card-pile registration has been frozen.</para>
	///     <para xml:lang="zh-CN">获取卡牌牌堆注册是否已冻结。</para>
	/// </summary>
	public static bool IsFrozen { get; private set; }

	private ModCardPileRegistry(string modId)
	{
		_modId = modId;
		_logger = RitsuLibFramework.CreateLogger(modId, (LogType)0);
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Gets the registry for <paramref name="modId" />, creating it on first use.
	///     </para>
	///     <para xml:lang="zh-CN">获取 <paramref name="modId" /> 的注册表，并在首次使用时创建。</para>
	/// </summary>
	/// <param name="modId">
	///     <para xml:lang="en">The owning mod ID.</para>
	///     <para xml:lang="zh-CN">所属模组 ID。</para>
	/// </param>
	public static ModCardPileRegistry For(string modId)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
		modId = modId.Trim();
		using (SyncRoot.EnterScope())
		{
			if (Registries.TryGetValue(modId, out ModCardPileRegistry value))
			{
				return value;
			}
			ModCardPileRegistry modCardPileRegistry = new ModCardPileRegistry(modId);
			Registries[modId] = modCardPileRegistry;
			return modCardPileRegistry;
		}
	}

	/// <summary>
	///     <para xml:lang="en">Freezes card-pile registration for the remainder of the process.</para>
	///     <para xml:lang="zh-CN">在当前进程的剩余生命周期内冻结卡牌牌堆注册。</para>
	/// </summary>
	/// <param name="reason">
	///     <para xml:lang="en">The reason reported in logs and late-registration errors.</para>
	///     <para xml:lang="zh-CN">写入日志和延迟注册错误的原因。</para>
	/// </param>
	internal static void FreezeRegistrations(string reason)
	{
		ModCardPileRegistry[] array;
		using (SyncRoot.EnterScope())
		{
			if (IsFrozen)
			{
				return;
			}
			IsFrozen = true;
			foreach (ModCardPileRegistry value in Registries.Values)
			{
				value._freezeReason = reason;
			}
			array = Registries.Values.ToArray();
		}
		ModCardPileRegistry[] array2 = array;
		for (int i = 0; i < array2.Length; i++)
		{
			array2[i]._logger.Info("[CardPiles] Pile registration is now frozen (" + reason + ").", 1);
		}
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Registers a card pile owned by this registry's mod. Repeating the same local stem for the
	///         same mod returns the existing definition.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册由此注册表所属模组拥有的卡牌牌堆。同一模组重复注册相同本地名称时返回现有定义。
	///     </para>
	/// </summary>
	/// <param name="localStem">
	///     <para xml:lang="en">The identifier local to the owning mod.</para>
	///     <para xml:lang="zh-CN">所属模组内的本地标识符。</para>
	/// </param>
	/// <param name="spec">
	///     <para xml:lang="en">The pile configuration.</para>
	///     <para xml:lang="zh-CN">牌堆配置。</para>
	/// </param>
	public ModCardPileDefinition RegisterOwned(string localStem, ModCardPileSpec spec)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(localStem, "localStem");
		ArgumentNullException.ThrowIfNull(spec, "spec");
		string qualifiedCardPileId = ModContentRegistry.GetQualifiedCardPileId(_modId, localStem);
		return RegisterCore(qualifiedCardPileId, spec);
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Registers a card pile with a global ID. Prefer <see cref="M:STS2RitsuLib.CardPiles.ModCardPileRegistry.RegisterOwned(System.String,STS2RitsuLib.CardPiles.ModCardPileSpec)" /> for mod-qualified
	///         IDs.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         使用全局 ID 注册卡牌牌堆。需要模组限定 ID 时优先使用 <see cref="M:STS2RitsuLib.CardPiles.ModCardPileRegistry.RegisterOwned(System.String,STS2RitsuLib.CardPiles.ModCardPileSpec)" />。
	///     </para>
	/// </summary>
	/// <param name="id">
	///     <para xml:lang="en">The global pile ID. Cross-mod ownership conflicts are rejected.</para>
	///     <para xml:lang="zh-CN">全局牌堆 ID。不同模组间的所有权冲突会被拒绝。</para>
	/// </param>
	/// <param name="spec">
	///     <para xml:lang="en">The pile configuration.</para>
	///     <para xml:lang="zh-CN">牌堆配置。</para>
	/// </param>
	public ModCardPileDefinition Register(string id, ModCardPileSpec spec)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
		ArgumentNullException.ThrowIfNull(spec, "spec");
		return RegisterCore(id, spec);
	}

	/// <summary>
	///     <para xml:lang="en">Tries to get a registered definition by pile ID.</para>
	///     <para xml:lang="zh-CN">尝试按牌堆 ID 获取已注册定义。</para>
	/// </summary>
	public static bool TryGet(string id, out ModCardPileDefinition definition)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
		using (SyncRoot.EnterScope())
		{
			return Definitions.TryGetValue(NormalizeId(id), out definition);
		}
	}

	/// <summary>
	///     <para xml:lang="en">Gets the registered definition for <paramref name="id" />.</para>
	///     <para xml:lang="zh-CN">获取 <paramref name="id" /> 的已注册定义。</para>
	/// </summary>
	public static ModCardPileDefinition Get(string id)
	{
		if (!TryGet(id, out ModCardPileDefinition definition))
		{
			throw new KeyNotFoundException("Card pile '" + NormalizeId(id) + "' is not registered.");
		}
		return definition;
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Gets the registered mod card-pile definition represented by a <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.PileType" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         获取 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.PileType" /> 所表示的已注册模组卡牌牌堆定义。
	///     </para>
	/// </summary>
	/// <param name="value">
	///     <para xml:lang="en">The dynamic card-pile value to resolve.</para>
	///     <para xml:lang="zh-CN">要解析的动态卡牌牌堆值。</para>
	/// </param>
	/// <returns>
	///     <para xml:lang="en">The registered mod card-pile definition.</para>
	///     <para xml:lang="zh-CN">已注册的模组卡牌牌堆定义。</para>
	/// </returns>
	/// <exception cref="T:System.Collections.Generic.KeyNotFoundException">
	///     <para xml:lang="en"><paramref name="value" /> is not a registered mod card pile.</para>
	///     <para xml:lang="zh-CN"><paramref name="value" /> 不是已注册的模组卡牌牌堆。</para>
	/// </exception>
	public static ModCardPileDefinition Get(PileType value)
	{
		//IL_0000: Unknown result type (might be due to invalid IL or missing references)
		//IL_0022: Unknown result type (might be due to invalid IL or missing references)
		//IL_002d: Expected I4, but got Unknown
		if (!TryGetByPileType(value, out ModCardPileDefinition definition))
		{
			throw new KeyNotFoundException($"PileType '0x{(int)value:X8}' is not a registered mod card pile.");
		}
		return definition;
	}

	/// <summary>
	///     <para xml:lang="en">Tries to get the ID of the mod that registered <paramref name="pileId" />.</para>
	///     <para xml:lang="zh-CN">尝试获取注册 <paramref name="pileId" /> 的模组 ID。</para>
	/// </summary>
	public static bool TryGetOwnerModId(string pileId, out string modId)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(pileId, "pileId");
		using (SyncRoot.EnterScope())
		{
			if (Definitions.TryGetValue(NormalizeId(pileId), out ModCardPileDefinition value))
			{
				modId = value.ModId;
				return true;
			}
		}
		modId = string.Empty;
		return false;
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Tries to get the registered definition represented by <paramref name="value" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         尝试获取 <paramref name="value" /> 所表示的已注册定义。
	///     </para>
	/// </summary>
	public static bool TryGetByPileType(PileType value, out ModCardPileDefinition definition)
	{
		//IL_0010: Unknown result type (might be due to invalid IL or missing references)
		using (SyncRoot.EnterScope())
		{
			return DefinitionsByPileType.TryGetValue(value, out definition);
		}
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Gets whether <paramref name="value" /> represents a registered mod card pile.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         获取 <paramref name="value" /> 是否表示已注册的模组卡牌牌堆。
	///     </para>
	/// </summary>
	public static bool IsModPileType(PileType value)
	{
		//IL_0010: Unknown result type (might be due to invalid IL or missing references)
		using (SyncRoot.EnterScope())
		{
			return DefinitionsByPileType.ContainsKey(value);
		}
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Returns the deterministic <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.PileType" /> for <paramref name="id" />. The ID does
	///         not need to be registered.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         返回 <paramref name="id" /> 对应的确定性 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.PileType" />。该 ID 无需已注册。
	///     </para>
	/// </summary>
	public static PileType GetPileType(string id)
	{
		//IL_000c: Unknown result type (might be due to invalid IL or missing references)
		ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
		return DynamicEnumValueRegistry<PileType>.GetValue(id);
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Tries to return the deterministic <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.PileType" /> for <paramref name="id" />. The ID
	///         does not need to be registered.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         尝试返回 <paramref name="id" /> 对应的确定性 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.PileType" />。该 ID 无需已注册。
	///     </para>
	/// </summary>
	public static bool TryGetPileType(string id, out PileType value)
	{
		//IL_000d: Unknown result type (might be due to invalid IL or missing references)
		//IL_0013: Expected I4, but got Unknown
		ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
		try
		{
			value = (PileType)(int)DynamicEnumValueRegistry<PileType>.GetValue(id);
			return true;
		}
		catch (InvalidOperationException)
		{
			value = (PileType)0;
			return false;
		}
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Tries to resolve a registered pile ID, vanilla <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.PileType" /> name, or deterministic
	///         dynamic value. Registered pile IDs take precedence.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         尝试解析已注册牌堆 ID、原版 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.PileType" /> 名称或确定性动态值。已注册牌堆 ID 优先。
	///     </para>
	/// </summary>
	public static bool TryResolvePileType(string idOrEnumName, out PileType value)
	{
		//IL_0030: Unknown result type (might be due to invalid IL or missing references)
		//IL_0036: Expected I4, but got Unknown
		ArgumentException.ThrowIfNullOrWhiteSpace(idOrEnumName, "idOrEnumName");
